package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

@RunWith(JUnit4.class)
public class JsonWriter_value_TriageGen0Test {

    private JsonWriter jsonWriter;

    @Before
    public void setup() throws IOException {
        StringWriter writer = new StringWriter();
        jsonWriter = new JsonWriter(writer);
    }

    @After
    public void tearDown() {
        jsonWriter = null;
    }

    @Test
    public void testValue_Long_Positive() throws IOException {
        jsonWriter.value(12345L);
        assertEquals("{\"value\":12345}", jsonWriter.toString());
    }

    @Test
    public void testValue_Long_Negative() throws IOException {
        jsonWriter.value(-12345L);
        assertEquals("{\"value\":-12345}", jsonWriter.toString());
    }

    @Test
    public void testValue_Long_Zero() throws IOException {
        jsonWriter.value(0L);
        assertEquals("{\"value\":0}", jsonWriter.toString());
    }

    @Test
    public void testValue_Long_Null() throws IOException {
        jsonWriter.value(null);
        assertThrows(NullPointerException.class, jsonWriter::toString);
    }

    @Test
    public void testValue_Long_IOException() throws IOException {
        jsonWriter = new JsonWriter(null);
        assertThrows(IOException.class, jsonWriter::value);
    }

    @Test
    public void testValue_Long_Lenient() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(12345L);
        assertEquals("{\"value\":12345}", jsonWriter.toString());
    }

    @Test
    public void testValue_Long_HtmlSafe() throws IOException {
        jsonWriter.setHtmlSafe(true);
        jsonWriter.value(12345L);
        assertEquals("{\"value\":12345}", jsonWriter.toString());
    }

    @Test
    public void testValue_Long_SerializeNulls() throws IOException {
        jsonWriter.setSerializeNulls(true);
        jsonWriter.value(12345L);
        assertEquals("{\"value\":12345}", jsonWriter.toString());
    }
}
